        ((ControllableClock) clock).setInstant(Instant.parse("2026-09-29T11:50:00Z"));
        assertApiStatus(() -> service.submitReceipt("INC-N-5",
                new NotificationReceiptRequest("甲", requestId(), "冒名签收人", "覆盖内容")),
